/bin/zsh -c "rtk proxy python3 - <<'PY'
from pathlib import Path
import hashlib,json,os,subprocess
out=Path.cwd(); snap=out.parent/'snapshot'; m=json.loads((out.parent/'manifest.json').read_text()); modes=json.loads((snap/'handoffs/shared-review-launch-repair-T-003-attempt-2/source-modes.json').read_text())['entries']; by={e['path']:e for e in m['allowed_inputs']}
assert len(modes)==len(by)-1
(out/'tmp').mkdir(exist_ok=True); work=out/'work'; work.mkdir(exist_ok=True)
for e in modes:
 assert e['sha256']==by[e['path']]['sha256']; assert e['mode'] in (420,493)
for e in m['allowed_inputs']:
 b=(snap/e['path']).read_bytes(); assert hashlib.sha256(b).hexdigest()==e['sha256']; p=work/e['path']; p.parent.mkdir(parents=True,exist_ok=True); assert not p.exists(),str(p); p.write_bytes(b)
for e in modes:
 p=work/e['path']; p.chmod(e['mode']); assert p.stat().st_mode&0o777==e['mode']
for d in json.loads((snap/'handoffs/shared-review-launch-repair-T-003-attempt-2/registry-topology.json').read_text())['directories']:
 (work/d).mkdir(parents=True,exist_ok=True)
ev=work/'specs/shared-review-launch-repair/verification/T-003'; ev.mkdir(parents=True,exist_ok=True)
record={'verified_input_count':len(by),'source_modes_verified':len(modes),'inputs':m['allowed_inputs']}
(ev/'input-verification.json').write_text(json.dumps(record,indent=2)+'\\n')
cmd=['rtk','proxy','bash',str(work/'scripts/check-sdd-structure.sh'),str(work),'shared-review-launch-repair']; r=subprocess.run(cmd,cwd=out,capture_output=True,text=True,env={**os.environ,'TMPDIR':str(out/'tmp'),'PYTHONDONTWRITEBYTECODE':'1'})
record={'argv':cmd,'cwd':str(out),'exit':r.returncode,'stdout':r.stdout,'stderr':r.stderr}; (ev/'structure.json').write_text(json.dumps(record,indent=2)+'\\n'); print(json.dumps(record,indent=2)); assert r.returncode==0
PY"

